tool_calls.arguments:
{"command":"kubectl -n default get deploy app -o jsonpath='{.spec.template.spec.containers[0].image}'; echo; for i in 1 2 3; do
  P=$(kubectl get pods -n default -l app=app -o jsonpath='{.items[0].metadata.name}');
  d=$(kubectl get pod "$P" -o jsonpath='{.status.containerStatuses[0].imageID}');
  echo "old: $P  imageID=$d"; break
done"}

{"command":"for p in $(kubectl -n default get pods -l app=app -o name); do
  image=$(kubectl get pod $p -n default -o jsonpath='{.spec.containers[0].image}');
  digest=$(kubectl get pod $p -n default -o jsonpath='{.status.containerStatuses[0].imageID}');
  echo "$p  image=$image  digest=$digest";
done; echo "=== RS ==="; kubectl get rs -n default; echo "=== deploy ==="; kubectl get deploy app -o jsonpath='image={.spec.template.spec.containers[0].image} policy={.spec.template.spec.containers[0].imagePullPolicy}'"}

