  id=$(kubectl -n default get pod "$p" -o jsonpath='{.status.containerStatuses[0].imageID}');
  echo "pod=$p  image=$im  imageID=$id";
done; echo "=== direct digests ===";
for p in $(kubectl -n default get pods -l app=app -o name); do
